#!/usr/bin/env bash
# Re-trace the script lockup from the original raster.
#
# The raster is NOT in the repo (same rule as brand/traces/: the traces in
# traces/ are the source of truth for the letterforms). This script is here so
# the separation can be re-run, and argued with, if the artwork ever turns up
# again or is redrawn.
#
#   ./trace.sh /path/to/artwork.png
#
# The artwork is three tones: an acid fill, a cream inner ribbon, and a black
# outer keyline. Two of them are traced; the keyline is regenerated by
# compose.py as a stroke, so it can be re-weighted.
set -euo pipefail
SRC=${1:?usage: trace.sh <artwork.png>}
cd "$(dirname "$0")"
mkdir -p traces

# union: every inked pixel, keyline included. A plain luminance threshold.
convert "$SRC" -colorspace gray -threshold 55% -negate traces/union.pbm

# cream: the pale inner ribbon. The BLUE channel is the discriminator, not
# luminance: acid (#CAFE04) is dark in blue and cream (#F2F6D8) is bright,
# while in luminance the two are close enough to merge.
convert "$SRC" -channel B -separate -threshold 43% -negate traces/cream.pbm

# acid: union minus cream.
convert traces/union.pbm traces/cream.pbm -compose MinusSrc -composite traces/acid.pbm

# Trace at NATIVE resolution. Upscaling the mask first (2x) inflated the
# curve count from 223 to 1204 and the file tenfold without adding fidelity:
# potrace is smoothing a bitmap, so a bigger bitmap only means more noise to
# follow.
for m in union cream acid; do
  potrace -s --flat -a 1.2 -O 0.3 -o "traces/$m.svg" "traces/$m.pbm"
done
rm -f traces/*.pbm

python3 compose.py
